import{_ as r,C as n,o as t,c as l,j as a,a as s,b as d,w as o,E as c,a2 as g,a3 as h}from"./chunks/framework.pb1iZPmZ.js";const P=JSON.parse('{"title":"14.5 System Design: Databases & Storage Hierarchy","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.5-databases-storage.md","filePath":"system-design/14.5-databases-storage.md"}'),m={name:"system-design/14.5-databases-storage.md"};function p(y,e,u,f,b,S){const i=n("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"_14-5-system-design-databases-storage-hierarchy",tabindex:"-1"},[s("14.5 System Design: Databases & Storage Hierarchy "),a("a",{class:"header-anchor",href:"#_14-5-system-design-databases-storage-hierarchy","aria-label":'Permalink to "14.5 System Design: Databases & Storage Hierarchy"'},"​")],-1)),(t(),d(g,null,{default:o(()=>[c(i,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20AppServers%5B%22Application%20Tier%22%5D%0A%20%20%20%20%20%20%20%20Node1%5B%22Node%20Server%201%22%5D%0A%20%20%20%20%20%20%20%20Node2%5B%22Node%20Server%202%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20MongoReplicaSet%5B%22MongoDB%203-Node%20Replica%20Set%20(High%20Availability)%22%5D%0A%20%20%20%20%20%20%20%20Primary%5B(%22Primary%20Node%3A%20Writes%20%26%20Strong%20Reads%22)%5D%0A%20%20%20%20%20%20%20%20Sec1%5B(%22Secondary%201%3A%20Read%20Replica%20(Oplog%20Sync)%22)%5D%0A%20%20%20%20%20%20%20%20Sec2%5B(%22Secondary%202%3A%20Read%20Replica%20(Oplog%20Sync)%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Node1%20%26%20Node2%20--%3E%7CWrites%3A%20POST%20%2Fsignup%2C%20POST%20%2Flogin%7C%20Primary%0A%20%20%20%20Node1%20%26%20Node2%20--%3E%7CReads%3A%20GET%20%2Fdashboard%20Hydration%7C%20Sec1%20%26%20Sec2%0A%20%20%20%20Primary%20-.-%3E%7CAsync%20Oplog%20Replication%7C%20Sec1%20%26%20Sec2%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=h('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Database and storage architecture governs how persistent state, transactional integrity, data durability, and query performance are guaranteed across disk, memory, and distributed storage engines.</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Database Engine</strong>: MongoDB v7.0/8.0 running on localhost:27017 ([<code>app.js:12</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L12)).</li><li><strong>ODM</strong>: Mongoose v9.0.0 providing schema modeling, connection pooling, and object mapping.</li><li><strong>Collections</strong>: <ul><li><code>employees</code>: Stores user identity documents.</li><li><code>sessions</code>: Managed by <code>connect-mongo</code> storing serialized session states.</li></ul></li><li><strong>Indexes</strong>: Default B-Tree on <code>_id</code>; background TTL index on <code>sessions.expires</code>.</li></ul><hr><h2 id="_3-database-paradigm-storage-engine-comparison" tabindex="-1">3. Database Paradigm &amp; Storage Engine Comparison <a class="header-anchor" href="#_3-database-paradigm-storage-engine-comparison" aria-label="Permalink to &quot;3. Database Paradigm &amp; Storage Engine Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Database Paradigm</th><th style="text-align:left;">Core Mechanism</th><th style="text-align:left;">ACID Guarantee</th><th style="text-align:left;">CAP Classification</th><th style="text-align:left;">Optimal Fit Domain</th><th style="text-align:left;">Fit for This Project</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Document NoSQL (MongoDB)</strong></td><td style="text-align:left;"><strong>BSON trees on WiredTiger engine</strong></td><td style="text-align:left;"><strong>Single-document ACID; multi-document transactions</strong></td><td style="text-align:left;"><strong>CP (Consistent / Partition Tolerant)</strong></td><td style="text-align:left;"><strong>JSON object models, flexible catalogs, session stores</strong></td><td style="text-align:left;"><strong>High (Selected for document mapping &amp; session support)</strong></td></tr><tr><td style="text-align:left;"><strong>Relational (PostgreSQL)</strong></td><td style="text-align:left;">Tables, rows, foreign keys</td><td style="text-align:left;">Full ACID (Multi-row isolation)</td><td style="text-align:left;">CA / CP</td><td style="text-align:left;">Relational medical billing, insurance records, prescriptions</td><td style="text-align:left;">High for complex medical records, overkill for auth</td></tr><tr><td style="text-align:left;"><strong>In-Memory (Redis)</strong></td><td style="text-align:left;">RAM key-value structures</td><td style="text-align:left;">Single-command atomicity</td><td style="text-align:left;">CP / AP</td><td style="text-align:left;">Sub-millisecond session caching, rate limiting</td><td style="text-align:left;">Excellent as a cache ahead of MongoDB</td></tr><tr><td style="text-align:left;"><strong>Wide-Column (Cassandra)</strong></td><td style="text-align:left;">LSM-Tree on commit log</td><td style="text-align:left;">Eventual consistency (BASE)</td><td style="text-align:left;">AP (Available / Partition Tolerant)</td><td style="text-align:left;">High-velocity time-series (patient ICU telemetry)</td><td style="text-align:left;">Unsuitable for strong auth consistency</td></tr></tbody></table><hr><h2 id="_4-cap-theorem-pacelc-analysis-for-this-system" tabindex="-1">4. CAP Theorem &amp; PACELC Analysis for This System <a class="header-anchor" href="#_4-cap-theorem-pacelc-analysis-for-this-system" aria-label="Permalink to &quot;4. CAP Theorem &amp; PACELC Analysis for This System&quot;">​</a></h2><ul><li><strong>CAP Position</strong>: <strong>CP (Consistency + Partition Tolerance)</strong>. In the event of a network partition, MongoDB stops accepting writes on isolated nodes rather than risking stale or split-brain credential writes.</li><li><strong>PACELC Position</strong>: <strong>PC/EC</strong> (If Partition: Consistency; Else: Consistency over Latency). For an authentication gateway, strong read-after-write consistency is mandatory—when a user registers, their immediate login attempt must find the newly written record.</li></ul><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: Standalone MongoDB instance handles read/write volume easily.</li><li><strong>100x Load</strong>: Disk I/O bottlenecks emerge because every authenticated request issues a read query to <code>sessions</code> and <code>employees</code>.</li><li><strong>1000x Load</strong>: Write throughput saturates the single primary node&#39;s storage engine.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><ol><li><strong>Deploy a 3-Node Replica Set</strong>: 1 Primary for writes, 2 Secondaries for read replication, enabling automatic failover in &lt;12 seconds if the primary crashes.</li><li><strong>Read-Preference Routing</strong>: Route <code>res.locals.user</code> hydration queries to secondary replicas (<code>readPreference: &#39;secondaryPreferred&#39;</code>), reserving the primary exclusively for login and registration writes.</li><li><strong>Partitioning &amp; Sharding</strong>: If the hospital network expands to 500,000 clinicians across multiple medical centers, shard the <code>employees</code> collection using hashed sharding on <code>username</code>.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We use MongoDB on the WiredTiger storage engine, which provides document-level concurrency and BSON serialization. In CAP theorem terms, it operates as a CP system prioritizing consistency over availability during network partitions. To scale this to enterprise production, I would deploy a three-node replica set with automatic election failover and offload hydration read queries to secondaries.&quot;</p></blockquote>',21))])}const A=r(m,[["render",p]]);export{P as __pageData,A as default};
